/*
 * VertexFileReader.H - Read external marker positions from .vertex files
 *
 * Part of the arbitrary geometry support for IAMReX.
 * Enables loading wing planforms generated by mosquito-cfd Python tools.
 *
 * File format:
 *   <number_of_markers>
 *   x1 y1 z1
 *   x2 y2 z2
 *   ...
 */

#ifndef VERTEX_FILE_READER_H
#define VERTEX_FILE_READER_H

#include <AMReX_RealVect.H>
#include <AMReX_Vector.H>
#include <AMReX_Print.H>
#include <string>
#include <fstream>
#include <sstream>

namespace IAMReX {

/**
 * Read marker positions from a .vertex file.
 *
 * @param filename Path to the .vertex file
 * @param markers Output vector of marker positions
 * @param center Position offset to apply to all markers
 * @param scale Scale factor to apply to all markers
 * @return Number of markers read
 */
inline int ReadVertexFile(
    const std::string& filename,
    amrex::Vector<amrex::RealVect>& markers,
    const amrex::RealVect& center = amrex::RealVect(0.0, 0.0, 0.0),
    amrex::Real scale = 1.0)
{
    std::ifstream file(filename);
    if (!file.is_open()) {
        amrex::Print() << "ERROR: Cannot open vertex file: " << filename << "\n";
        amrex::Abort("Failed to open vertex file");
        return 0;
    }

    // Read marker count from first line
    int n_markers = 0;
    file >> n_markers;

    if (n_markers <= 0) {
        amrex::Print() << "ERROR: Invalid marker count in vertex file: " << n_markers << "\n";
        amrex::Abort("Invalid vertex file format");
        return 0;
    }

    markers.resize(n_markers);

    // Read marker positions
    for (int i = 0; i < n_markers; ++i) {
        amrex::Real x, y, z;
        file >> x >> y >> z;

        if (file.fail()) {
            amrex::Print() << "ERROR: Failed to read marker " << i << " from " << filename << "\n";
            amrex::Abort("Failed to parse vertex file");
            return i;
        }

        // Apply scale and translate to center
        markers[i][0] = x * scale + center[0];
        markers[i][1] = y * scale + center[1];
        markers[i][2] = z * scale + center[2];
    }

    amrex::Print() << "Read " << n_markers << " markers from " << filename << "\n";
    return n_markers;
}

/**
 * Compute bounding box of markers.
 */
inline void ComputeMarkerBounds(
    const amrex::Vector<amrex::RealVect>& markers,
    amrex::RealVect& lo,
    amrex::RealVect& hi)
{
    if (markers.empty()) {
        lo = amrex::RealVect(0.0, 0.0, 0.0);
        hi = amrex::RealVect(0.0, 0.0, 0.0);
        return;
    }

    lo = markers[0];
    hi = markers[0];

    for (const auto& m : markers) {
        for (int d = 0; d < AMREX_SPACEDIM; ++d) {
            lo[d] = std::min(lo[d], m[d]);
            hi[d] = std::max(hi[d], m[d]);
        }
    }
}

/**
 * Compute centroid of markers.
 */
inline amrex::RealVect ComputeMarkerCentroid(
    const amrex::Vector<amrex::RealVect>& markers)
{
    amrex::RealVect centroid(0.0, 0.0, 0.0);

    if (markers.empty()) {
        return centroid;
    }

    for (const auto& m : markers) {
        centroid += m;
    }

    centroid /= static_cast<amrex::Real>(markers.size());
    return centroid;
}

} // namespace IAMReX

#endif // VERTEX_FILE_READER_H